import app from 'flarum/forum/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import extractText from 'flarum/common/utils/extractText';
import { createReportLink, deleteSponsor, eraseOptIns, exportOptIns, listSponsors, revokeReportLink, saveSponsor, showSponsor } from '../../common/sponsors';
const blank = () => ({
  name: '',
  logoUrl: '',
  websiteUrl: '',
  privacyUrl: '',
  description: ''
});

/**
 * Managers' sponsors: add and edit them, make or turn off the secret report
 * link, download the opted-in members, erase their opt-ins.
 */
export default class SponsorsModal extends FormModal {
  sponsors = null;
  editing = null;
  form = null;
  /** A report link just made: shown once. */
  reportUrl = null;
  oninit(vnode) {
    super.oninit(vnode);
    this.reload();
  }
  className() {
    return 'SponsorsModal Modal--large';
  }
  title() {
    return this.t('manage_title');
  }
  t(key, params = {}) {
    return app.translator.trans(`ernestdefoe-giveaways.forum.sponsors.${key}`, params);
  }
  reload() {
    listSponsors().then(list => this.sponsors = list).catch(() => {
      /* app.request already showed the alert */
    }).finally(() => m.redraw());
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, this.form ? this.editor() : this.list());
  }
  list() {
    if (!this.sponsors) return m(LoadingIndicator, null);
    return [m("ul", {
      className: "SponsorsModal-list"
    }, this.sponsors.map(s => m("li", {
      className: "SponsorsModal-row"
    }, m("span", {
      className: "SponsorsModal-name"
    }, s.name), m(Button, {
      className: "Button Button--sm",
      icon: "fas fa-pencil-alt",
      onclick: () => this.edit(s)
    }, this.t('edit')))), !this.sponsors.length && m("li", {
      className: "helpText"
    }, this.t('none'))), m(Button, {
      className: "Button Button--primary",
      icon: "fas fa-plus",
      onclick: () => this.edit(null)
    }, this.t('add'))];
  }
  edit(s) {
    this.reportUrl = null;
    if (!s) {
      this.editing = null;
      this.form = blank();
      return;
    }
    showSponsor(s.id).then(full => {
      this.editing = full;
      this.form = {
        name: full.name,
        logoUrl: full.logoUrl ?? '',
        websiteUrl: full.websiteUrl,
        privacyUrl: full.privacyUrl,
        description: full.description ?? ''
      };
    }).catch(() => {
      /* app.request already showed the alert */
    }).finally(() => m.redraw());
  }
  editor() {
    const f = this.form;
    const field = (key, label, help, area = false) => m("div", {
      className: "Form-group"
    }, m("label", null, this.t(label)), area ? m("textarea", {
      className: "FormControl",
      rows: 3,
      value: f[key],
      oninput: e => f[key] = e.target.value
    }) : m("input", {
      className: "FormControl",
      value: f[key],
      oninput: e => f[key] = e.target.value
    }), help && m("p", {
      className: "helpText"
    }, this.t(help)));
    return m("div", {
      className: "Form"
    }, field('name', 'name'), field('logoUrl', 'logo'), field('websiteUrl', 'website', 'website_help'), field('privacyUrl', 'privacy', 'privacy_help'), field('description', 'description', undefined, true), m("div", {
      className: "Form-group SponsorsModal-actions"
    }, m(Button, {
      type: "submit",
      className: "Button Button--primary",
      loading: this.loading
    }, this.t('save')), m(Button, {
      className: "Button",
      onclick: () => this.form = null
    }, this.t('back')), this.editing && m(Button, {
      className: "Button Button--danger",
      onclick: () => this.remove()
    }, this.t('delete'))), this.editing && this.privacyTools(this.editing));
  }

  /** The report link, the export and the erase button. */
  privacyTools(s) {
    return m("section", {
      className: "SponsorsModal-privacy"
    }, m("h4", null, this.t('report_heading')), m("p", {
      className: "helpText"
    }, this.t('report_help')), this.reportUrl && m("input", {
      className: "FormControl SponsorsModal-reportUrl",
      readonly: true,
      value: this.reportUrl,
      onfocus: e => e.target.select()
    }), m("div", {
      className: "SponsorsModal-actions"
    }, m(Button, {
      className: "Button",
      icon: "fas fa-link",
      onclick: () => this.makeReportLink(s)
    }, this.t(s.reportLinkCreatedAt ? 'report_new' : 'report_make')), s.reportLinkCreatedAt && m(Button, {
      className: "Button",
      icon: "fas fa-unlink",
      onclick: () => this.revokeReport(s)
    }, this.t('report_off'))), m("h4", null, this.t('optins_heading', {
      count: s.optInCount ?? 0
    })), m("p", {
      className: "helpText"
    }, this.t('optins_help')), m("div", {
      className: "SponsorsModal-actions"
    }, m(Button, {
      className: "Button",
      icon: "fas fa-file-csv",
      onclick: () => exportOptIns(s).catch(() => {
        /* app.request already showed the alert */
      })
    }, this.t('export')), m(Button, {
      className: "Button Button--danger",
      icon: "fas fa-eraser",
      onclick: () => this.erase(s)
    }, this.t('erase'))));
  }
  makeReportLink(s) {
    if (s.reportLinkCreatedAt && !confirm(extractText(this.t('report_new_confirm')))) return;
    createReportLink(s.id).then(url => {
      this.reportUrl = url;
      s.reportLinkCreatedAt = new Date().toISOString();
    }).catch(() => {
      /* app.request already showed the alert */
    }).finally(() => m.redraw());
  }
  revokeReport(s) {
    revokeReportLink(s.id).then(() => {
      s.reportLinkCreatedAt = null;
      this.reportUrl = null;
    }).catch(() => {
      /* app.request already showed the alert */
    }).finally(() => m.redraw());
  }
  erase(s) {
    if (!confirm(extractText(this.t('erase_confirm', {
      sponsor: s.name
    })))) return;
    eraseOptIns(s.id).then(() => {
      s.optInCount = 0;
      app.alerts.show({
        type: 'success'
      }, this.t('erased'));
    }).catch(() => {
      /* app.request already showed the alert */
    }).finally(() => m.redraw());
  }
  remove() {
    const s = this.editing;
    if (!s || !confirm(extractText(this.t('delete_confirm', {
      sponsor: s.name
    })))) return;
    deleteSponsor(s.id).then(() => {
      this.form = null;
      this.reload();
    }).catch(() => {
      /* app.request already showed the alert */
    });
  }
  onsubmit(e) {
    e.preventDefault();
    if (!this.form) return;
    this.loading = true;
    saveSponsor(this.form, this.editing?.id).then(() => {
      this.form = null;
      app.alerts.show({
        type: 'success'
      }, this.t('saved'));
      this.reload();
    }).catch(err => this.onerror(err)).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-giveaways', 'forum/sponsors/SponsorsModal', SponsorsModal);